import { basename, dirname, join } from "node:path";

import { z } from "zod/mini";

import { SKILL_FILE_NAME } from "../constants/general.js";
import { RULESYNC_SKILLS_RELATIVE_DIR_PATH } from "../constants/rulesync-paths.js";
import {
  RulesyncSkill,
  type RulesyncSkillFrontmatter,
  RulesyncSkillFrontmatterSchema,
} from "../features/skills/rulesync-skill.js";
import { AiDirFile } from "../types/ai-dir.js";
import { stripControlCharacters } from "../utils/control-characters.js";
import { formatError } from "../utils/error.js";
import {
  checkPathTraversal,
  directoryExists,
  ensureDir,
  listSubdirectoryNames,
  removeDirectory,
  writeFileBuffer,
  writeFileContent,
} from "../utils/file.js";
import { stringifyFrontmatter } from "../utils/frontmatter.js";
import { ConsoleLogger } from "../utils/logger.js";
import { resetRunWarningState } from "../utils/warned-once.js";

const logger = new ConsoleLogger({ verbose: false, silent: true });

const maxSkillSizeBytes = 1024 * 1024; // 1MB
const maxSkillsCount = 1000;

/**
 * Encoding of the `body` field of an other file in the MCP API.
 * `utf-8` keeps text files human readable, `base64` preserves binary files byte for byte.
 */
type McpSkillFileEncoding = "utf-8" | "base64";

/**
 * Type for other files in MCP API (string-based for easier AI agent use)
 */
type McpSkillFile = {
  name: string;
  body: string;
  encoding?: McpSkillFileEncoding;
};

/**
 * Whether the buffer survives a UTF-8 round-trip without losing any byte.
 * Buffers that do not (e.g. images) must be transported as base64.
 */
function isUtf8RoundTrippable(fileBuffer: Buffer): boolean {
  return fileBuffer.equals(Buffer.from(fileBuffer.toString("utf-8"), "utf-8"));
}

/**
 * Convert AiDirFile to McpSkillFile
 */
function aiDirFileToMcpSkillFile(file: AiDirFile): McpSkillFile {
  const encoding: McpSkillFileEncoding = isUtf8RoundTrippable(file.fileBuffer) ? "utf-8" : "base64";

  return {
    name: file.relativeFilePathToDirPath,
    body: file.fileBuffer.toString(encoding),
    encoding,
  };
}

/**
 * Decode the body of an other file according to its declared encoding.
 * Base64 bodies are validated because Buffer.from silently drops invalid characters.
 */
function decodeMcpSkillFileBody(file: McpSkillFile): Buffer {
  const encoding = file.encoding ?? "utf-8";

  if (encoding === "utf-8") {
    return Buffer.from(file.body, "utf-8");
  }

  const fileBuffer = Buffer.from(file.body, "base64");
  // Node accepts both the standard and the URL-safe alphabet, and padding is optional,
  // so normalize the input before comparing it with the canonical re-encoding.
  const normalizedBody = file.body
    .replaceAll(/\s/g, "")
    .replaceAll("-", "+")
    .replaceAll("_", "/")
    .replaceAll(/=+$/g, "");
  if (fileBuffer.toString("base64").replaceAll(/=+$/g, "") !== normalizedBody) {
    throw new Error(`Invalid base64 body for other file ${file.name}: expected canonical base64`);
  }

  return fileBuffer;
}

/**
 * Convert McpSkillFile to AiDirFile
 */
function mcpSkillFileToAiDirFile(file: McpSkillFile): AiDirFile {
  return {
    relativeFilePathToDirPath: file.name,
    fileBuffer: decodeMcpSkillFileBody(file),
  };
}

/**
 * Extract directory name from relative path
 * @example ".rulesync/skills/my-skill" -> "my-skill"
 */
function extractDirName(relativeDirPathFromCwd: string): string {
  const dirName = basename(relativeDirPathFromCwd);
  if (!dirName) {
    throw new Error(`Invalid path: ${relativeDirPathFromCwd}`);
  }
  return dirName;
}

/**
 * Tool to list all skills from .rulesync/skills/\*\/SKILL.md
 */
async function listSkills(): Promise<
  Array<{
    relativeDirPathFromCwd: string;
    frontmatter: RulesyncSkillFrontmatter;
  }>
> {
  // The MCP server outlives a single call, and the diagnostics a skill read
  // reports are reported once per run; without this, only the first listing of
  // a session would say what it refused to carry.
  resetRunWarningState();

  const skillsDir = join(process.cwd(), RULESYNC_SKILLS_RELATIVE_DIR_PATH);

  // A project that has not created any skill yet is the ordinary case, not a
  // read failure: reading the directory reports that as an error, and this
  // logger prints an error however quiet it is asked to be.
  if (!(await directoryExists(skillsDir))) {
    return [];
  }

  try {
    // Find all skill directories (directories containing SKILL.md). Read rather
    // than globbed, so a name holding a backslash is the name on disk and not
    // the two-segment path a glob rewrites it into.
    const dirNames = await listSubdirectoryNames(skillsDir);

    const skills = await Promise.all(
      dirNames.map(async (dirName) => {
        try {
          // Read the skill using RulesyncSkill
          const skill = await RulesyncSkill.fromDir({
            dirName,
          });

          const frontmatter = skill.getFrontmatter();

          return {
            relativeDirPathFromCwd: join(RULESYNC_SKILLS_RELATIVE_DIR_PATH, dirName),
            frontmatter,
          };
        } catch (error) {
          // The name is stripped in both halves of the line: the error carries
          // the same name back, and a control character left in either can
          // erase the line and pass what follows off as rulesync's own output.
          logger.error(
            `Failed to read skill directory ${stripControlCharacters(dirName)}: ` +
              stripControlCharacters(formatError(error)),
          );
          return null;
        }
      }),
    );

    // Filter out null values (failed reads)
    return skills.filter((skill): skill is NonNullable<typeof skill> => skill !== null);
  } catch (error) {
    logger.error(
      `Failed to read skills directory (${RULESYNC_SKILLS_RELATIVE_DIR_PATH}): ${formatError(error)}`,
    );
    return [];
  }
}

/**
 * Tool to get detailed information about a specific skill
 */
async function getSkill({ relativeDirPathFromCwd }: { relativeDirPathFromCwd: string }): Promise<{
  relativeDirPathFromCwd: string;
  frontmatter: RulesyncSkillFrontmatter;
  body: string;
  otherFiles: McpSkillFile[];
}> {
  checkPathTraversal({
    relativePath: relativeDirPathFromCwd,
    intendedRootDir: process.cwd(),
  });

  const dirName = extractDirName(relativeDirPathFromCwd);

  try {
    const skill = await RulesyncSkill.fromDir({
      dirName,
    });

    return {
      relativeDirPathFromCwd: join(RULESYNC_SKILLS_RELATIVE_DIR_PATH, dirName),
      frontmatter: skill.getFrontmatter(),
      body: skill.getBody(),
      otherFiles: skill.getOtherFiles().map(aiDirFileToMcpSkillFile),
    };
  } catch (error) {
    throw new Error(
      `Failed to read skill directory ${relativeDirPathFromCwd}: ${formatError(error)}`,
      {
        cause: error,
      },
    );
  }
}

/**
 * Tool to create or update a skill (upsert operation)
 */
async function putSkill({
  relativeDirPathFromCwd,
  frontmatter,
  body,
  otherFiles = [],
}: {
  relativeDirPathFromCwd: string;
  frontmatter: RulesyncSkillFrontmatter;
  body: string;
  otherFiles?: McpSkillFile[];
}): Promise<{
  relativeDirPathFromCwd: string;
  frontmatter: RulesyncSkillFrontmatter;
  body: string;
  otherFiles: McpSkillFile[];
}> {
  checkPathTraversal({
    relativePath: relativeDirPathFromCwd,
    intendedRootDir: process.cwd(),
  });

  const dirName = extractDirName(relativeDirPathFromCwd);

  // Convert McpSkillFile to AiDirFile for RulesyncSkill (also validates base64 bodies)
  const aiDirFiles = otherFiles.map(mcpSkillFileToAiDirFile);

  // Check file size constraint, measured in bytes so binary other files are counted accurately
  const estimatedSize =
    Buffer.byteLength(JSON.stringify(frontmatter), "utf-8") +
    Buffer.byteLength(body, "utf-8") +
    aiDirFiles.reduce(
      (acc, file) => acc + file.relativeFilePathToDirPath.length + file.fileBuffer.byteLength,
      0,
    );
  if (estimatedSize > maxSkillSizeBytes) {
    throw new Error(
      `Skill size ${estimatedSize} bytes exceeds maximum ${maxSkillSizeBytes} bytes (1MB) for ${relativeDirPathFromCwd}`,
    );
  }

  try {
    // Check skill count constraint
    const existingSkills = await listSkills();
    const isUpdate = existingSkills.some(
      (skill) => skill.relativeDirPathFromCwd === join(RULESYNC_SKILLS_RELATIVE_DIR_PATH, dirName),
    );

    if (!isUpdate && existingSkills.length >= maxSkillsCount) {
      throw new Error(
        `Maximum number of skills (${maxSkillsCount}) reached in ${RULESYNC_SKILLS_RELATIVE_DIR_PATH}`,
      );
    }

    // Create a new RulesyncSkill instance for validation
    const skill = new RulesyncSkill({
      outputRoot: process.cwd(),
      relativeDirPath: RULESYNC_SKILLS_RELATIVE_DIR_PATH,
      dirName,
      frontmatter,
      body,
      otherFiles: aiDirFiles,
      validate: true,
    });

    // Ensure skill directory exists
    const skillDirPath = join(process.cwd(), RULESYNC_SKILLS_RELATIVE_DIR_PATH, dirName);
    await ensureDir(skillDirPath);

    // Write the SKILL.md file
    const skillFilePath = join(skillDirPath, SKILL_FILE_NAME);
    const skillFileContent = stringifyFrontmatter(body, frontmatter);
    await writeFileContent(skillFilePath, skillFileContent);

    // Write other files byte for byte so binary files are not corrupted
    for (const file of aiDirFiles) {
      const fileName = file.relativeFilePathToDirPath;
      // Validate file path to prevent path traversal
      checkPathTraversal({
        relativePath: fileName,
        intendedRootDir: skillDirPath,
      });
      const filePath = join(skillDirPath, fileName);
      // Ensure subdirectory exists if file has path separators
      const fileDir = join(skillDirPath, dirname(fileName));
      if (fileDir !== skillDirPath) {
        await ensureDir(fileDir);
      }
      await writeFileBuffer(filePath, file.fileBuffer);
    }

    return {
      relativeDirPathFromCwd: join(RULESYNC_SKILLS_RELATIVE_DIR_PATH, dirName),
      frontmatter: skill.getFrontmatter(),
      body: skill.getBody(),
      otherFiles: skill.getOtherFiles().map(aiDirFileToMcpSkillFile),
    };
  } catch (error) {
    throw new Error(
      `Failed to write skill directory ${relativeDirPathFromCwd}: ${formatError(error)}`,
      {
        cause: error,
      },
    );
  }
}

/**
 * Tool to delete a skill
 */
async function deleteSkill({
  relativeDirPathFromCwd,
}: {
  relativeDirPathFromCwd: string;
}): Promise<{
  relativeDirPathFromCwd: string;
}> {
  checkPathTraversal({
    relativePath: relativeDirPathFromCwd,
    intendedRootDir: process.cwd(),
  });

  const dirName = extractDirName(relativeDirPathFromCwd);
  const skillDirPath = join(process.cwd(), RULESYNC_SKILLS_RELATIVE_DIR_PATH, dirName);

  try {
    // Check if skill directory exists before attempting to delete
    if (await directoryExists(skillDirPath)) {
      await removeDirectory(skillDirPath);
    }

    return {
      relativeDirPathFromCwd: join(RULESYNC_SKILLS_RELATIVE_DIR_PATH, dirName),
    };
  } catch (error) {
    throw new Error(
      `Failed to delete skill directory ${relativeDirPathFromCwd}: ${formatError(error)}`,
      {
        cause: error,
      },
    );
  }
}

/**
 * Schema for other files in a skill directory
 */
const McpSkillFileSchema = z.object({
  name: z.string(),
  body: z.string(),
  encoding: z.optional(z.enum(["utf-8", "base64"])),
});

/**
 * Schema for skill-related tool parameters
 */
const skillToolSchemas = {
  listSkills: z.object({}),
  getSkill: z.object({
    relativeDirPathFromCwd: z.string(),
  }),
  putSkill: z.object({
    relativeDirPathFromCwd: z.string(),
    frontmatter: RulesyncSkillFrontmatterSchema,
    body: z.string(),
    otherFiles: z.optional(z.array(McpSkillFileSchema)),
  }),
  deleteSkill: z.object({
    relativeDirPathFromCwd: z.string(),
  }),
} as const;

/**
 * Tool definitions for skill-related operations
 */
export const skillTools = {
  listSkills: {
    name: "listSkills",
    description: `List all skills from ${join(RULESYNC_SKILLS_RELATIVE_DIR_PATH, "*", SKILL_FILE_NAME)} with their frontmatter.`,
    parameters: skillToolSchemas.listSkills,
    execute: async () => {
      const skills = await listSkills();
      const output = { skills };
      return JSON.stringify(output, null, 2);
    },
  },
  getSkill: {
    name: "getSkill",
    description:
      'Get detailed information about a specific skill including SKILL.md content and other files. relativeDirPathFromCwd parameter is required. Each other file carries an encoding field: "utf-8" for text files and "base64" for binary files.',
    parameters: skillToolSchemas.getSkill,
    execute: async (args: { relativeDirPathFromCwd: string }) => {
      const result = await getSkill({ relativeDirPathFromCwd: args.relativeDirPathFromCwd });
      return JSON.stringify(result, null, 2);
    },
  },
  putSkill: {
    name: "putSkill",
    description:
      'Create or update a skill (upsert operation). relativeDirPathFromCwd, frontmatter, and body parameters are required. otherFiles is optional; each other file may set encoding to "base64" for binary content (defaults to "utf-8").',
    parameters: skillToolSchemas.putSkill,
    execute: async (args: {
      relativeDirPathFromCwd: string;
      frontmatter: RulesyncSkillFrontmatter;
      body: string;
      otherFiles?: McpSkillFile[];
    }) => {
      const result = await putSkill({
        relativeDirPathFromCwd: args.relativeDirPathFromCwd,
        frontmatter: args.frontmatter,
        body: args.body,
        otherFiles: args.otherFiles,
      });
      return JSON.stringify(result, null, 2);
    },
  },
  deleteSkill: {
    name: "deleteSkill",
    description:
      "Delete a skill directory and all its contents. relativeDirPathFromCwd parameter is required.",
    parameters: skillToolSchemas.deleteSkill,
    execute: async (args: { relativeDirPathFromCwd: string }) => {
      const result = await deleteSkill({ relativeDirPathFromCwd: args.relativeDirPathFromCwd });
      return JSON.stringify(result, null, 2);
    },
  },
} as const;
